return_1w = #{return1w}, return_1m = #{return1m}, return_3m = #{return3m}, return_6m = #{return6m}, return_1y = #{return1y}, return_3y = #{return3y}, return_5y = #{return5y}, max_drawdown_1y = #{maxDrawdown1y}, sharp_ratio_1y = #{sharpRatio1y}, volatility_1y = #{volatility1y}, morningstar_rating = #{morningstarRating}, galaxy_rating = #{galaxyRating}
